CREATE TABLE public.webbookmarkitems
(
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NULL,
    "Shortcut" text NULL,
    "Description" text NULL,
    "URL" text NULL,
    "URLs" text NULL,
    "IsVisible" boolean NOT NULL,
    "BookmarkGroup" text NULL DEFAULT '',
    "SortOrder" integer NOT NULL,
    "Profile" text NULL DEFAULT '',
    "IsFavorite" boolean NOT NULL DEFAULT false
);

CREATE INDEX "IX_webbookmarkitems_Profile"
    ON public.webbookmarkitems ("Profile");

CREATE INDEX "IX_webbookmarkitems_BookmarkGroup_SortOrder"
    ON public.webbookmarkitems ("BookmarkGroup", "SortOrder");
